"""Position windows over visits."""


def minutes_between(visits, low, high):
    """Return the minutes of the visits at positions low to high, both included. Positions start at 1."""
    return [x.minutes for x in visits[low - 1:high - 1]]


def first_minutess(visits, n):
    """Return the minutes of the first n visits."""
    return minutes_between(visits, 1, n)


def page_names(visits):
    """Return the distinct page values, in first-seen order."""
    names = []
    for x in visits:
        if x.page not in names:
            names.append(x.page)
    return names


def group_by_page(visits):
    """Return a dict from page to the list of visits with that page."""
    groups = {}
    for x in visits:
        groups.setdefault(x.page, []).append(x)
    return groups

